1import { useState, useEffect, useMemo, useCallback } from "react";
2import Header from "./components/Header";
3import EntryCard from "./components/EntryCard";
4import Drawer from "./components/Drawer";
5
6const ENTRIES_PER_PAGE = 5;
7
8function App() {
9  const [entries, setEntries] = useState([]);
10  const [isLoading, setIsLoading] = useState(true);
11  const [error, setError] = useState(null);
12  const [refreshKey, setRefreshKey] = useState(0);
13  const [selectedEntry, setSelectedEntry] = useState(null);
14  const [query, setQuery] = useState("");
15  const [currentPage, setCurrentPage] = useState(1);
16
17  const filteredEntries = useMemo(function () {
18    if (!query.trim()) return entries;
19    const lower = query.toLowerCase();
20    return entries.filter(function (entry) {
21      return (
22        entry.title.toLowerCase().includes(lower) ||
23        entry.content.toLowerCase().includes(lower)
24      );
25    });
26  }, [entries, query]);
27
28  const totalPages = useMemo(function () {
29    return Math.ceil(filteredEntries.length / ENTRIES_PER_PAGE);
30  }, [filteredEntries]);
31
32  const pagedEntries = useMemo(function () {
33    const start = (currentPage - 1) * ENTRIES_PER_PAGE;
34    return filteredEntries.slice(start, start + ENTRIES_PER_PAGE);
35  }, [filteredEntries, currentPage]);
36
37  useEffect(function () {
38    async function loadEntries() {
39      setIsLoading(true);
40      setError(null);
41      try {
42        const res = await fetch("https://api.programiz.pro/api/Demo/v1/journal-entries");
43        if (!res.ok) {
44          throw new Error("Could not load entries. Status: " + res.status);
45        }
46        const data = await res.json();
47        const mapped = data.map((post) => {
48          return {
49            ...post,
50            date: new Date(post.date).toLocaleDateString("en-US", {
51              year: "numeric", month: "short", day: "numeric"
52            }).toUpperCase()
53          };
54        });
55        setEntries(mapped);
56        setIsLoading(false);
57      } catch (err) {
58        setError(err.message);
59        setIsLoading(false);
60      }
61    }
62    loadEntries();
63  }, [refreshKey]);
64
65  const handleRefresh = useCallback(function () {
66    setRefreshKey(function (k) { return k + 1; });
67  }, []);
68
69  const handleSelectEntry = useCallback(function (entry) {
70    setSelectedEntry(entry);
71  }, []);
72
73  const handleCloseDrawer = useCallback(function () {
74    setSelectedEntry(null);
75  }, []);
76
77  function handleQueryChange(newQuery) {
78    setQuery(newQuery);
79    setCurrentPage(1);
80  }
81
82  function handleNext() {
83    setCurrentPage(function (p) { return Math.min(p + 1, totalPages); });
84  }
85
86  function handlePrev() {
87    setCurrentPage(function (p) { return Math.max(p - 1, 1); });
88  }
89
90  return (
91    <div className="main-container">
92      <Header query={query} onQueryChange={handleQueryChange} />
93      <section className="entries-section">
94        <div className="entry-list-header">
95          <h3>Recent Entries</h3>
96          <span className="entry-count">{filteredEntries.length}</span>
97          {query && <span className="entry-count">of {entries.length}</span>}
98          <button className="btn btn-secondary" onClick={handleRefresh}>Refresh</button>
99        </div>
100        {isLoading ? (
101          <p className="loading-state">Loading entries...</p>
102        ) : error ? (
103          <div className="error-banner">
104            <p className="error-label">Something went wrong.</p>
105            <p className="error-detail">{error}</p>
106          </div>
107        ) : pagedEntries.length === 0 ? (
108          <p className="empty-state">No entries found.</p>
109        ) : (
110          pagedEntries.map((entry) => (
111            <EntryCard
112              key={entry.id}
113              id={entry.id}
114              title={entry.title}
115              date={entry.date}
116              content={entry.content}
117              author={entry.author}
118              onSelect={handleSelectEntry}
119            />
120          ))
121        )}
122        {!isLoading && !error && totalPages > 1 && (
123          <div className="pagination">
124            <button
125              className="btn btn-secondary"
126              onClick={handlePrev}
127              disabled={currentPage === 1}
128            >
129              Previous
130            </button>
131            <span className="pagination-info">Page {currentPage} of {totalPages}</span>
132            <button
133              className="btn btn-secondary"
134              onClick={handleNext}
135              disabled={currentPage === totalPages}
136            >
137              Next
138            </button>
139          </div>
140        )}
141      </section>
142      <Drawer entry={selectedEntry} onClose={handleCloseDrawer} />
143    </div>
144  );
145}
146
147export default App;

